#include <bits/stdc++.h>
using namespace std;

int n;
vector<int> startNode;
vector<vector<pair<int,int>>> adj;
vector<int> degV;
vector<int> dsu, ssz;
vector<int> nxt, prv;
vector<int> headE, tailE;
vector<int> pnode, pedge;
int sStart, bestT;

int find(int x){ 
    int r=x;
    while(dsu[r]!=r) r=dsu[r];
    while(dsu[x]!=r){ int t=dsu[x]; dsu[x]=r; x=t; }
    return r;
}
void unite(int a,int b){ a=find(a); b=find(b); if(a==b) return; if(ssz[a]<ssz[b]) swap(a,b); dsu[b]=a; ssz[a]+=ssz[b]; }

bool sethead_ok(int u,int b){
    if(headE[u]!=-1) return false;
    if(prv[b]!=-1) return false;
    if(tailE[u]!=-1 && find(b)==find(tailE[u]) && ssz[find(b)]!=degV[u]) return false;
    return true;
}
bool settail_ok(int u,int a){
    if(tailE[u]!=-1) return false;
    if(nxt[a]!=-1) return false;
    if(headE[u]!=-1 && find(a)==find(headE[u]) && ssz[find(a)]!=degV[u]) return false;
    return true;
}
bool link_ok(int u,int a,int b){
    if(nxt[a]!=-1) return false;
    if(prv[b]!=-1) return false;
    if(a==b) return false;
    int ra=find(a), rb=find(b);
    if(ra==rb) return false;
    if(tailE[u]!=-1 && a==tailE[u]) return false;
    if(headE[u]!=-1 && b==headE[u]) return false;
    if(headE[u]!=-1 && tailE[u]!=-1){
        int rh=find(headE[u]), rt=find(tailE[u]);
        bool contH=(rh==ra||rh==rb);
        bool contT=(rt==ra||rt==rb);
        if(contH&&contT && ssz[ra]+ssz[rb]!=degV[u]) return false;
    }
    return true;
}
void do_sethead(int u,int b){ headE[u]=b; }
void do_settail(int u,int a){ tailE[u]=a; }
void do_link(int a,int b){ nxt[a]=b; prv[b]=a; unite(a,b); }

void dfs(int u,int parent,int in_he){
    if(tailE[u]==-1 && settail_ok(u,in_he)){
        if(u<bestT) bestT=u;
    }
    for(auto &pr: adj[u]){
        int v=pr.first, outhe=pr.second;
        if(v==parent) continue;
        if(link_ok(u,in_he,outhe)){
            pnode[v]=u; pedge[v]=outhe;
            dfs(v,u,outhe);
        }
    }
}

int main(){
    int T; scanf("%d",&T);
    while(T--){
        scanf("%d",&n);
        startNode.assign(n+1,0);
        for(int i=1;i<=n;i++) scanf("%d",&startNode[i]);
        adj.assign(n+1,{});
        degV.assign(n+1,0);
        for(int i=0;i<n-1;i++){
            int a,b; scanf("%d %d",&a,&b);
            int he1=2*i, he2=2*i+1;
            adj[a].push_back({b,he1});
            adj[b].push_back({a,he2});
        }
        for(int u=1;u<=n;u++) degV[u]=adj[u].size();
        int m=2*max(0,n-1);
        dsu.resize(m); ssz.resize(m);
        nxt.assign(m,-1); prv.assign(m,-1);
        for(int i=0;i<m;i++){ dsu[i]=i; ssz[i]=1; }
        headE.assign(n+1,-1); tailE.assign(n+1,-1);
        pnode.assign(n+1,0); pedge.assign(n+1,-1);
        vector<int> ans(n+1,0);
        if(n==1){ printf("1\n"); continue; }
        for(int x=1;x<=n;x++){
            sStart=startNode[x];
            bestT=n+1;
            for(auto &pr: adj[sStart]){
                int v=pr.first, he=pr.second;
                if(sethead_ok(sStart,he)){
                    pnode[v]=sStart; pedge[v]=he;
                    dfs(v,sStart,he);
                }
            }
            vector<int> path;
            int cur=bestT;
            while(cur!=sStart){ path.push_back(cur); cur=pnode[cur]; }
            path.push_back(sStart);
            reverse(path.begin(),path.end());
            do_sethead(path[0], pedge[path[1]]);
            for(int i=1;i+1<(int)path.size();i++){
                int u=path[i];
                int in_he=pedge[u]^1;
                int out_he=pedge[path[i+1]];
                do_link(in_he,out_he);
            }
            do_settail(path.back(), pedge[path.back()]^1);
            ans[x]=bestT;
        }
        for(int i=1;i<=n;i++) printf("%d%c",ans[i], i==n?'\n':' ');
    }
    return 0;
}

